    end
    on_intel do
      url "https://blindpass.app/cli/0.2.51/blindpass-0.2.51-darwin-x64.tar.gz"
      sha256 "ba4b947b288c04da738c566a0b59f20f62a4a87747fab1997c9d3f7615fa60f8"
    end
  end

  on_linux do
    on_arm do
