      sha256 "168d14cc95e0f2c6ccb75979911a0a540fcc489f31488e5394447cff06be3c67"
    end
    on_intel do
      url "https://blindpass.app/cli/0.2.51/blindpass-0.2.51-linux-x64.tar.gz"
